using System.ComponentModel.DataAnnotations;

namespace DocSummary.Models;

public class SummarizeRequest
{
    [Required]
    [MinLength(1)]
    public string DocumentText { get; set; } = string.Empty;
}

namespace DocSummary.Models;

public class SummarizeResponse
{
    public string Summary { get; set; } = string.Empty;
}

namespace DocSummary.Services;

public interface IDocumentSummarizer
{
    string Summarize(string documentText);
}

namespace DocSummary.Services;

/// <summary>
/// Extractive summarizer that selects the most relevant sentences based on word frequency.
/// </summary>
public class ExtractiveSummarizer : IDocumentSummarizer
{
    private const int MaxSummarySentences = 3;

    private static readonly HashSet<string> StopWords = new(StringComparer.OrdinalIgnoreCase)
    {
        "a", "an", "the", "and", "or", "but", "is", "are", "was", "were",
        "in", "on", "at", "to", "for", "of", "with", "by", "it", "this",
        "that", "from", "as", "be", "has", "have", "had", "not", "no",
        "do", "does", "did", "will", "would", "can", "could", "should",
        "may", "might", "shall", "so", "if", "then", "than", "too", "very",
        "just", "about", "up", "out", "its", "his", "her", "he", "she",
        "they", "them", "we", "you", "i", "me", "my", "your", "our"
    };

    public string Summarize(string documentText)
    {
        var sentences = SplitIntoSentences(documentText);

        if (sentences.Count <= MaxSummarySentences)
            return string.Join(" ", sentences);

        var wordFrequencies = ComputeWordFrequencies(sentences);
        var scoredSentences = ScoreSentences(sentences, wordFrequencies);

        // Pick top sentences but preserve their original order
        var topIndices = scoredSentences
            .OrderByDescending(s => s.Score)
            .Take(MaxSummarySentences)
            .Select(s => s.Index)
            .OrderBy(i => i)
            .ToList();

        return string.Join(" ", topIndices.Select(i => sentences[i]));
    }

    private static List<string> SplitIntoSentences(string text)
    {
        return text
            .Split(['.', '!', '?'], StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Where(s => s.Length > 0)
            .Select(s => s + ".")
            .ToList();
    }

    private static Dictionary<string, int> ComputeWordFrequencies(List<string> sentences)
    {
        var frequencies = new Dictionary<string, int>(StringComparer.OrdinalIgnoreCase);

        foreach (var sentence in sentences)
        {
            foreach (var word in GetWords(sentence))
            {
                if (!StopWords.Contains(word))
                    frequencies[word] = frequencies.GetValueOrDefault(word) + 1;
            }
        }

        return frequencies;
    }

    private static List<(int Index, double Score)> ScoreSentences(
        List<string> sentences,
        Dictionary<string, int> wordFrequencies)
    {
        return sentences
            .Select((sentence, index) =>
            {
                var words = GetWords(sentence);
                var score = words
                    .Where(w => !StopWords.Contains(w))
                    .Sum(w => wordFrequencies.GetValueOrDefault(w));

                // Normalize by word count to avoid bias toward longer sentences
                var normalizedScore = words.Count > 0 ? (double)score / words.Count : 0;
                return (Index: index, Score: normalizedScore);
            })
            .ToList();
    }

    private static List<string> GetWords(string text)
    {
        return text
            .Split([' ', '\t', '\r', '\n', ',', ';', ':', '"', '\'', '(', ')', '[', ']'],
                StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)
            .Select(w => w.Trim('.', '!', '?'))
            .Where(w => w.Length > 0)
            .ToList();
    }
}

